import asyncio
from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware

from crews.crew_manager import kickoff_crew

app = FastAPI(title="PT-agents")

# Enable CORS for React frontend
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_methods=["*"],
    allow_headers=["*"],
)


@app.get("/")
async def ping():
    return {"Hello": "World"}


